#include "libtmux_spike/transport.hpp"
#include <chrono>
#include <cstdint>
#include <cstdio>

int main() {
  constexpr std::uint64_t iterations = 100000;
  std::uint64_t checksum = 0;
  std::uint64_t error_count = 0;
  const auto started = std::chrono::steady_clock::now();
  for (std::uint64_t index = 0; index < iterations; ++index) {
    const auto result = libtmux::spike::validate_command_request(
        libtmux::spike::CommandRequest{});
    if (!result) { ++checksum; ++error_count; }
  }
  const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::steady_clock::now() - started).count();
  std::printf("{\"checksum\":%llu,\"elapsed_ns\":%lld,\"error_count\":%llu,\"iterations\":%llu}\n",
      static_cast<unsigned long long>(checksum),
      static_cast<long long>(elapsed),
      static_cast<unsigned long long>(error_count),
      static_cast<unsigned long long>(iterations));
  return checksum == iterations ? 0 : 3;
}

#include "libtmux_spike/server.hpp"
#include <utility>
int main() {
  auto server = libtmux::spike::Server::create(
      libtmux::spike::ConnectionConfig{});
  if (!server) {
    return 2;
  }
  libtmux::spike::CommandRequest request{};
  return server->execute(std::move(request)) ? 1 : 0;
}

